import json,re,hashlib,collections
from pathlib import Path
root=Path("/home/sasaki/datasets/openloris/corridor1-1-m8-native-ba-context-v1")
old=Path("/home/sasaki/datasets/openloris/corridor1-1-m8-native-cluster8-v1")
out={}
for arm,reference in [("strict","strict"),("cluster8","cluster8-a")]:
 log=(root/(arm+".log")).read_text();calls=[];current=None
 for line in log.splitlines():
  if line.startswith("rig-ba-context:"):
   assert current is None
   current={"context":line,"failures":{},"accepted":0,"iterations":0}
  elif line.startswith("sfm-debug-ba-lm-quality:"):
   assert current is not None
   current["iterations"]+=1
   if "linear_failure=" in line:
    kind=re.search(r"linear_failure=(\w+)",line)[1]
    current["failures"][kind]=current["failures"].get(kind,0)+1
   elif " accepted=true " in line:current["accepted"]+=1
  elif line.startswith("rig-ba-backend:"):
   assert current is not None
   assert int(re.search(r"iterations=(\d+)",line)[1])==current["iterations"]
   assert int(re.search(r"accepted=(\d+)",line)[1])==current["accepted"]
   current["summary"]=line;calls.append(current);current=None
 assert current is None and len(calls)==86
 for name in ("cameras.txt","images.txt","points3D.txt"):
  assert (root/arm/"model"/name).read_bytes()==(old/reference/"model"/name).read_bytes()
 counts=collections.Counter()
 for call in calls:counts.update(call["failures"])
 out[arm]={"calls":calls,"failure_counts":dict(counts),"first_failure_call_1_based":next(i+1 for i,c in enumerate(calls) if c["failures"]),"model_bytes_exact_to_PR94":True,"log_sha256":hashlib.sha256(log.encode()).hexdigest()}
print(json.dumps(out))
